const dealTotal=x=>x.deal?x.deal.rate*x.deal.posts:0;
function campStats(c){const s=sumPosts(c.ccs);let committed=0,spent=0;c.ccs.forEach(x=>{if(COMMITTED.includes(x.status)&&x.deal){committed+=dealTotal(x);spent+=x.deal.rate*Math.min(x.posts.length,x.deal.posts)}});(c.boosts||[]).forEach(b=>{committed+=b;spent+=b});s.committed=committed;s.spent=spent;s.remaining=c.budget-committed;s.unattributed=c.unattributed||0;s.wi=s.enrols;s.cpi=s.enrols?spent/s.enrols:0;s.cpe=s.cpi;s.live=c.ccs.filter(x=>x.status==='Live'||x.status==='Delivered').length;s.creators=c.ccs.length;return s}
